import{_ as a,o as n,c as p,a2 as t}from"./chunks/framework.DGvnA5EY.js";const g=JSON.parse('{"title":"附录 A 常用指令模板","description":"> 内容来源：WorkBuddy 官方指南（非官方整理，© 本指南作者，保留所有权利） 前面每章都给了提示词，但它们嵌在章节里，要读那一段才能抄。这份附录把通用型、框架型的提示词抽出来，整理成可以随手复制粘贴的模板。","frontmatter":{"title":"附录 A 常用指令模板"},"headers":[],"relativePath":"bluebook/附录/附录 A 常用指令模板/index.md","filePath":"bluebook/附录/附录 A 常用指令模板/index.md","lastUpdated":1792132442000}'),e={name:"bluebook/附录/附录 A 常用指令模板/index.md"};function l(i,s,o,d,r,c){return n(),p("div",null,[...s[0]||(s[0]=[t(`<h1 id="附录-a-常用指令模板" tabindex="-1">附录 A 常用指令模板 <a class="header-anchor" href="#附录-a-常用指令模板" aria-label="Permalink to &quot;附录 A 常用指令模板&quot;">​</a></h1><blockquote><p>内容来源：WorkBuddy 官方指南（非官方整理，© 本指南作者，保留所有权利）</p></blockquote><h2 id="这份附录是干什么的" tabindex="-1">这份附录是干什么的 <a class="header-anchor" href="#这份附录是干什么的" aria-label="Permalink to &quot;这份附录是干什么的&quot;">​</a></h2><p>前面每章都给了提示词，但它们嵌在章节里，要读那一段才能抄。这份附录把<strong>通用型、框架型</strong>的提示词抽出来，整理成可以随手复制粘贴的模板。</p><p><strong>收的是什么</strong>：能反复套用到任何任务的骨架提示词（定标、拆解、验收、复盘…）。 <strong>不收什么</strong>：第二～四篇里那些针对具体案例的完整实操提示词——那些属于付费内容（见购买指南）。</p><p><strong>统一约定</strong>：所有模板里 <code>【】</code> 里的内容是<strong>你要替换的占位符</strong>，抄完必须改成你的真实业务。</p><hr><h2 id="一、五问定标法-万能起手式" tabindex="-1">一、五问定标法（万能起手式） <a class="header-anchor" href="#一、五问定标法-万能起手式" aria-label="Permalink to &quot;一、五问定标法（万能起手式）&quot;">​</a></h2><p>这是全指南出现最多的一招。<strong>任何任务开工前，先用它把目标钉死</strong>——能省掉后面 80% 的返工。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在动手之前，请先用五问帮我把这件任务的规格定清楚：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 目标：做完之后，我要拿到的东西是什么？（一份文档？一个表格？一个网页？）</span></span>
<span class="line"><span>2. 受众：谁会看/会用它？（只给我自己看 / 团队 / 客户 / 领导）</span></span>
<span class="line"><span>3. 材料：我手上有哪些原始资料可以给你？（文件路径、链接、数据）</span></span>
<span class="line"><span>4. 格式：交付物要长什么样？（字数、章节、字段、风格）</span></span>
<span class="line"><span>5. 验收：怎么算做对了？（哪几点做到了就算合格）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>先把这五个问题的答案跟我确认一遍，我确认后再开始执行。</span></span></code></pre></div><p><strong>为什么有效</strong>：它强迫 AI 先复述需求，而不是直接开干。你在确认环节就能发现它理解偏了。</p><p><strong>验收标准</strong>：五问答案你能逐条点头；有歧义的地方你补充清楚。</p><hr><h2 id="二、先要草稿-别直接给最终结果" tabindex="-1">二、先要草稿，别直接给最终结果 <a class="header-anchor" href="#二、先要草稿-别直接给最终结果" aria-label="Permalink to &quot;二、先要草稿，别直接给最终结果&quot;">​</a></h2><p>新手最容易吃亏的一点：任务一交出去，AI 就闷头做完，你只能全盘接受或全盘重来。<strong>改成先要草稿</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这次先不要直接给我最终成品。先给我一版草稿或大纲，让我确认方向对不对：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 先说你打算怎么做（步骤、顺序、准备产出什么）</span></span>
<span class="line"><span>2. 先给我一个提纲/框架/样例，让我看结构</span></span>
<span class="line"><span>3. 我确认或提出修改后，你再往下做完整版</span></span>
<span class="line"><span></span></span>
<span class="line"><span>如果某一部分你觉得我给的信息不够，先问我，不要猜。</span></span></code></pre></div><p><strong>为什么有效</strong>：把&quot;一次赌一把&quot;变成&quot;两步走&quot;，返工成本降到 1/N。</p><p><strong>验收标准</strong>：草稿阶段你只花几分钟就能看出方向对不对。</p><hr><h2 id="三、给上下文-别让它猜" tabindex="-1">三、给上下文，别让它猜 <a class="header-anchor" href="#三、给上下文-别让它猜" aria-label="Permalink to &quot;三、给上下文，别让它猜&quot;">​</a></h2><p>同一句需求，给不给背景，结果质量差很多。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我这件任务的背景如下，请基于这些信息来做：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 我的身份/岗位：【如：市场部运营】</span></span>
<span class="line"><span>- 这件事的用途：【如：给老板汇报季度投放效果】</span></span>
<span class="line"><span>- 我已有的材料：【文件路径 / 链接 / 数据表】</span></span>
<span class="line"><span>- 我已经尝试过：【做过什么，为什么不行】</span></span>
<span class="line"><span>- 我最在意的点：【如：数据必须能溯源】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请在开始前复述一遍你的理解，我确认后再执行。</span></span></code></pre></div><p><strong>四类必须给的信息</strong>：你是谁、给谁看、手上有什么、卡在哪。</p><p><strong>验收标准</strong>：AI 的复述里没有你没说过的假设。</p><hr><h2 id="四、拆步骤-别让它一步跳到结果" tabindex="-1">四、拆步骤，别让它一步跳到结果 <a class="header-anchor" href="#四、拆步骤-别让它一步跳到结果" aria-label="Permalink to &quot;四、拆步骤，别让它一步跳到结果&quot;">​</a></h2><p>复杂任务（报告、方案、多步骤操作）必须先拆。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这件事比较大，请先拆成可执行的步骤，每步做完停下来等我确认：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 先列出完整步骤清单，让我看到全貌</span></span>
<span class="line"><span>2. 每次只做一步，做完给我结果，等我确认</span></span>
<span class="line"><span>3. 我说&quot;继续&quot;再进入下一步</span></span>
<span class="line"><span>4. 如果某一步出问题，停下来告诉我，不要自己绕过</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第一步先做：【步骤一】</span></span></code></pre></div><p><strong>为什么有效</strong>：一步一确认，出错时你损失的是一步，不是全部。</p><p><strong>验收标准</strong>：步骤清单里每一步都能独立验收。</p><hr><h2 id="五、要验收标准-别只看它说-完成了" tabindex="-1">五、要验收标准，别只看它说&quot;完成了&quot; <a class="header-anchor" href="#五、要验收标准-别只看它说-完成了" aria-label="Permalink to &quot;五、要验收标准，别只看它说&quot;完成了&quot;&quot;">​</a></h2><p>AI 说&quot;已完成&quot;不代表做对了。你必须<strong>事先定好验收标准</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这次任务的验收标准如下，做完请逐条自查并给我结果：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 【具体要求一，如：字数不少于 2000 字】</span></span>
<span class="line"><span>2. 【具体要求二，如：所有数据标明来源】</span></span>
<span class="line"><span>3. 【具体要求三，如：没有错别字和专业术语误用】</span></span>
<span class="line"><span></span></span>
<span class="line"><span>请在最后输出一份自检清单，逐条打勾并说明落在哪一节。</span></span></code></pre></div><p><strong>验收标准</strong>：AI 自己能说出做到了哪几条、没做到哪几条。</p><hr><h2 id="六、防幻觉-不确定的必须标出来" tabindex="-1">六、防幻觉：不确定的必须标出来 <a class="header-anchor" href="#六、防幻觉-不确定的必须标出来" aria-label="Permalink to &quot;六、防幻觉：不确定的必须标出来&quot;">​</a></h2><p>AI 会编。<strong>明确要求它标出不确定的部分</strong>，比事后你自己去核对高效得多。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>凡是你不确定的信息，请用【待核实】标记出来，不要写成确定的事实；</span></span>
<span class="line"><span>凡是推断，请标注【推断】并说明依据；</span></span>
<span class="line"><span>凡是事实，请尽量给出来源。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>不确定就直接说不确定，不要猜一个看起来合理的答案。</span></span></code></pre></div><p><strong>这一条在涉及数据、引用、政策、行业信息时特别重要</strong>，能挡掉大部分幻觉。</p><p><strong>验收标准</strong>：结果里不确定的部分都被标记出来，而不是混在正文里。</p><hr><h2 id="七、修坏文件前先给方案" tabindex="-1">七、修坏文件前先给方案 <a class="header-anchor" href="#七、修坏文件前先给方案" aria-label="Permalink to &quot;七、修坏文件前先给方案&quot;">​</a></h2><p>让它改文件、改代码、改配置时，先要方案再动手。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>在动手修改之前，先告诉我：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 你打算改哪些文件、每个文件改什么</span></span>
<span class="line"><span>2. 每处修改的理由</span></span>
<span class="line"><span>3. 可能的副作用或风险</span></span>
<span class="line"><span>4. 改完之后怎么验证</span></span>
<span class="line"><span></span></span>
<span class="line"><span>我确认后再执行。改动前先备份原文件。</span></span></code></pre></div><p><strong>为什么有效</strong>：改文件是有风险的动作，尤其是批量改。方案先行是最后一道防线。</p><p><strong>验收标准</strong>：你能看懂每一处改动的理由，不认可以拒绝。</p><hr><h2 id="八、要固定格式-方便下次复用" tabindex="-1">八、要固定格式，方便下次复用 <a class="header-anchor" href="#八、要固定格式-方便下次复用" aria-label="Permalink to &quot;八、要固定格式，方便下次复用&quot;">​</a></h2><p>同一个活干第二次时，不要重新写提示词——<strong>固化成模板</strong>。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>请把这次的完整做法固化成一个可复用的提示词模板，包含：</span></span>
<span class="line"><span>1. 变量位（用【】标注，说明每处该填什么）</span></span>
<span class="line"><span>2. 固定部分（不用改的开头结尾）</span></span>
<span class="line"><span>3. 使用说明（什么时候用、填完要注意什么）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>以后我说&quot;用【模板名】&quot;，你就按这个模板执行。</span></span></code></pre></div><p><strong>再用一步</strong>：如果这类活会反复做，可以用 <code>skill-creator</code> 把它变成真正的 Skill，以后连提示词都不用写。</p><p><strong>验收标准</strong>：下次用的时候，只改 <code>【】</code> 里的内容就能跑。</p><hr><h2 id="九、复盘-让下一次更好" tabindex="-1">九、复盘：让下一次更好 <a class="header-anchor" href="#九、复盘-让下一次更好" aria-label="Permalink to &quot;九、复盘：让下一次更好&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>这次任务做完了，请帮我复盘：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 这次哪些地方顺利，哪些地方返工了</span></span>
<span class="line"><span>2. 返工的原因是什么（是我没说清，还是你理解偏了）</span></span>
<span class="line"><span>3. 下次同类任务，我该怎么把需求说得更准</span></span>
<span class="line"><span>4. 给我一条可以直接复用的改进后的提示词</span></span></code></pre></div><p><strong>为什么值得做</strong>：这是唯一能让 AI &quot;越用越懂你&quot;的环节。每做一次复盘，下一次的成本都低一点。</p><hr><h2 id="十、说-不知道-比编答案强" tabindex="-1">十、说&quot;不知道&quot;比编答案强 <a class="header-anchor" href="#十、说-不知道-比编答案强" aria-label="Permalink to &quot;十、说&quot;不知道&quot;比编答案强&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>如果你不知道、没把握，或者需要联网才能确认，请直接说&quot;不知道&quot;，</span></span>
<span class="line"><span>不要给一个听起来合理的答案。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>明确告诉我：</span></span>
<span class="line"><span>1. 你能确定的部分是什么</span></span>
<span class="line"><span>2. 你不确定的部分是什么</span></span>
<span class="line"><span>3. 要确认这部分，我需要提供什么</span></span></code></pre></div><p><strong>这对应第一篇反复提到的&quot;预期误区&quot;</strong>——把 AI 当成一个很能干但会犯错的助手，而不是全知机器。</p><hr><h2 id="十一、给你的任务清单-打印贴墙" tabindex="-1">十一、给你的任务清单（打印贴墙） <a class="header-anchor" href="#十一、给你的任务清单-打印贴墙" aria-label="Permalink to &quot;十一、给你的任务清单（打印贴墙）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>编号</th><th>模板</th><th>什么时候用</th></tr></thead><tbody><tr><td>1</td><td>五问定标</td><td>任何任务开工前</td></tr><tr><td>2</td><td>先要草稿</td><td>输出物较大、不想赌</td></tr><tr><td>3</td><td>给上下文</td><td>AI 可能猜错时</td></tr><tr><td>4</td><td>拆步骤</td><td>多步骤复杂任务</td></tr><tr><td>5</td><td>要验收标准</td><td>需要判断做没做对</td></tr><tr><td>6</td><td>防幻觉标注</td><td>涉及数据、引用、政策</td></tr><tr><td>7</td><td>修文件先给方案</td><td>让它改动你的文件</td></tr><tr><td>8</td><td>固化成模板</td><td>同一类活会反复做</td></tr><tr><td>9</td><td>任务后复盘</td><td>每次做完一个任务</td></tr><tr><td>10</td><td>允许说不知道</td><td>任何时候</td></tr></tbody></table><p><strong>通用组合</strong>：1 → 2 → 5 是绝大多数任务的最小可用组合。复杂任务再加 3、4、6。</p><hr><h2 id="本附录任务清单" tabindex="-1">本附录任务清单 <a class="header-anchor" href="#本附录任务清单" aria-label="Permalink to &quot;本附录任务清单&quot;">​</a></h2><ul><li>[ ] 把「五问定标」抄进你的剪贴板，用一次看看效果</li><li>[ ] 挑 2 个你最常做的任务，各写一条带 <code>【】</code> 的提示词模板</li><li>[ ] 攒够 3 个模板后，用附录 B 的 Skill 清单看要不要固化成 Skill</li><li>[ ] 每次任务做完，用模板 9 复盘一次</li></ul><hr><p><em>本指南为第三方非官方整理，版权归作者所有，转载请注明出处。</em></p>`,70)])])}const u=a(e,[["render",l]]);export{g as __pageData,u as default};
